const MALE_POOL   = ['A', 'B', 'C', 'D']
const FEMALE_POOL = ['E', 'F', 'G', 'H']

// Hash uses the full instanceId string (which includes shot type + index)
// so each frame in a storyboard picks a different figure
function pickFigure(gender, instanceId) {
  const pool = gender === 'female' ? FEMALE_POOL : MALE_POOL
  let hash = 5381
  const str = String(instanceId || gender)
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) ^ str.charCodeAt(i)
    hash = hash & 0x7fffffff
  }
  return FIGURE_POOL[pool[hash % pool.length]]
}

// ─── FRAME CHROME ────────────────────────────────────────────────────────────
function frameBase(label) {
  return `
<rect width="${W}" height="${H}" fill="${BG}"/>
<rect x="0" y="0" width="${W}" height="${H}" fill="none" stroke="${FRAME}" stroke-width="1.5"/>
<rect x="8" y="8" width="${W - 16}" height="${H - 16}" fill="none" stroke="${FRAME}" stroke-width="0.5" stroke-dasharray="4 3" opacity="0.4"/>
<rect x="0" y="${H - 22}" width="${W}" height="22" fill="${LABEL_BG}" opacity="0.95"/>
<text x="10" y="${H - 8}" font-family="monospace" font-size="9" fill="${LINE}" opacity="0.8">${label}</text>
`
}

// Nested SVG crops the figure at the given viewBox window
function figureFrame(figureContent, vbX, vbY, vbW, vbH, par = 'xMidYMid slice') {
  return `<svg x="0" y="0" width="${W}" height="${H - 22}" viewBox="${vbX} ${vbY} ${vbW} ${vbH}" preserveAspectRatio="${par}">${figureContent}</svg>`
}

// ─── SHOT GENERATORS ─────────────────────────────────────────────────────────

function ecu(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('ECU — Extreme Close-Up')}
    ${figureFrame(fig, 115, 45, 150, 74)}
    <line x1="${W/3}" y1="0" x2="${W/3}" y2="${H-22}" stroke="${LINE}" stroke-width="0.3" opacity="0.15"/>
    <line x1="${W*2/3}" y1="0" x2="${W*2/3}" y2="${H-22}" stroke="${LINE}" stroke-width="0.3" opacity="0.15"/>
  `)
}

function cu(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('CU — Close-Up')}
    ${figureFrame(fig, 80, 45, 220, 108)}
  `)
}

function mcu(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('MCU — Medium Close-Up')}
    ${figureFrame(fig, 50, 45, 280, 138)}
  `)
}

function ms(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('MS — Medium Shot')}
    ${figureFrame(fig, 20, 40, 340, 168)}
  `)
}

function mws(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('MWS — Medium Wide Shot')}
    ${figureFrame(fig, 0, 40, 380, 188)}
    <line x1="0" y1="${H - 24}" x2="${W}" y2="${H - 24}" stroke="${LINE}" stroke-width="0.4" opacity="0.2"/>
  `)
}

function ws(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('WS — Wide Shot')}
    ${figureFrame(fig, -296, 30, 972, 480, 'xMidYMid meet')}
    <line x1="0" y1="${H * 0.87}" x2="${W}" y2="${H * 0.87}" stroke="${LINE}" stroke-width="0.5" opacity="0.2"/>
  `)
}

function ews(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('EWS — Extreme Wide Shot')}
    ${figureFrame(fig, -700, 30, 2040, 1006, 'xMidYMid meet')}
    <line x1="0" y1="${H * 0.78}" x2="${W}" y2="${H * 0.78}" stroke="${LINE}" stroke-width="0.5" opacity="0.15"/>
    <line x1="0" y1="${H * 0.65}" x2="${W}" y2="${H * 0.65}" stroke="${LINE}" stroke-width="0.3" opacity="0.1"/>
  `)
}

function ots(gender, instanceId) {
  const fig      = pickFigure(gender, instanceId)
  const oppGender = gender === 'male' ? 'female' : 'male'
  const figOpp   = pickFigure(oppGender, (instanceId || '') + 'opp')
  return svg(`
    ${frameBase('OTS — Over The Shoulder')}
    <g opacity="0.35">
      <svg x="-80" y="0" width="220" height="${H - 22}" viewBox="60 45 220 108" preserveAspectRatio="xMidYMid slice">${fig}</svg>
    </g>
    <svg x="120" y="0" width="200" height="${H - 22}" viewBox="80 45 220 108" preserveAspectRatio="xMidYMid slice">${figOpp}</svg>
    <line x1="80" y1="0" x2="160" y2="${H-22}" stroke="${LINE}" stroke-width="0.5" stroke-dasharray="3 2" opacity="0.25"/>
  `)
}

function two(gender, instanceId) {
  const fig      = pickFigure(gender, instanceId)
  const oppGender = gender === 'male' ? 'female' : 'male'
  const figOpp   = pickFigure(oppGender, (instanceId || '') + 'two')
  return svg(`
    ${frameBase('TWO — Two Shot')}
    <svg x="0" y="0" width="${W/2}" height="${H - 22}" viewBox="20 40 340 168" preserveAspectRatio="xMaxYMid slice">${fig}</svg>
    <svg x="${W/2}" y="0" width="${W/2}" height="${H - 22}" viewBox="20 40 340 168" preserveAspectRatio="xMinYMid slice">${figOpp}</svg>
    <line x1="${W/2}" y1="0" x2="${W/2}" y2="${H-22}" stroke="${LINE}" stroke-width="0.4" opacity="0.25"/>
  `)
}

function low(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('LOW — Low Angle')}
    <g transform="scale(1, 0.9) translate(0, ${Math.round(H * 0.05)})">
      ${figureFrame(fig, 50, 80, 280, 138)}
    </g>
    <line x1="${W * 0.1}" y1="${H - 22}" x2="${W * 0.45}" y2="${H * 0.28}" stroke="${LINE}" stroke-width="0.4" opacity="0.2"/>
    <line x1="${W * 0.9}" y1="${H - 22}" x2="${W * 0.55}" y2="${H * 0.28}" stroke="${LINE}" stroke-width="0.4" opacity="0.2"/>
    <text x="${W - 10}" y="18" font-family="monospace" font-size="7" fill="${LINE}" opacity="0.5" text-anchor="end">↑ cam</text>
  `)
}

function high(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('HIGH — High Angle')}
    <g transform="scale(1, 0.82) translate(0, ${Math.round(H * 0.12)})">
      ${figureFrame(fig, 50, 45, 280, 138)}
    </g>
    <line x1="${W * 0.1}" y1="0" x2="${W * 0.45}" y2="${H * 0.55}" stroke="${LINE}" stroke-width="0.4" opacity="0.2"/>
    <line x1="${W * 0.9}" y1="0" x2="${W * 0.55}" y2="${H * 0.55}" stroke="${LINE}" stroke-width="0.4" opacity="0.2"/>
    <text x="${W - 10}" y="18" font-family="monospace" font-size="7" fill="${LINE}" opacity="0.5" text-anchor="end">↓ cam</text>
  `)
}

function dutch(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  const cx = W / 2
  const cy = (H - 22) / 2
  return svg(`
    ${frameBase('DUTCH — Dutch Angle')}
    <g transform="rotate(-12, ${cx}, ${cy})">
      ${figureFrame(fig, 50, 45, 280, 138)}
    </g>
    <line x1="0" y1="${H * 0.18}" x2="${W}" y2="${H * 0.38}" stroke="${LINE}" stroke-width="0.5" opacity="0.18"/>
    <text x="${W - 10}" y="18" font-family="monospace" font-size="7" fill="${LINE}" opacity="0.5" text-anchor="end">⟳ tilt</text>
  `)
}

function pov(gender, instanceId) {
  const s = gender === 'male' ? 1 : 0.88
  return svg(`
    ${frameBase('POV — Point of View')}
    <line x1="${W/2}" y1="${H * 0.4}" x2="0" y2="${H - 22}" stroke="${LINE}" stroke-width="0.4" opacity="0.15"/>
    <line x1="${W/2}" y1="${H * 0.4}" x2="${W}" y2="${H - 22}" stroke="${LINE}" stroke-width="0.4" opacity="0.15"/>
    <line x1="${W/2}" y1="${H * 0.4}" x2="0" y2="0" stroke="${LINE}" stroke-width="0.3" opacity="0.08"/>
    <line x1="${W/2}" y1="${H * 0.4}" x2="${W}" y2="0" stroke="${LINE}" stroke-width="0.3" opacity="0.08"/>
    <circle cx="${W/2}" cy="${H * 0.4}" r="2" fill="${LINE}" opacity="0.4"/>
    <ellipse cx="${W * 0.3}" cy="${H * 0.91}" rx="${16 * s}" ry="${10 * s}" fill="${FILL}" stroke="${LINE}" stroke-width="1.2"/>
    <ellipse cx="${W * 0.7}" cy="${H * 0.91}" rx="${16 * s}" ry="${10 * s}" fill="${FILL}" stroke="${LINE}" stroke-width="1.2"/>
    <circle cx="${W/2}" cy="${H * 0.44}" r="4" fill="none" stroke="${LINE}" stroke-width="0.6" opacity="0.4"/>
    <line x1="${W/2 - 8}" y1="${H * 0.44}" x2="${W/2 + 8}" y2="${H * 0.44}" stroke="${LINE}" stroke-width="0.5" opacity="0.4"/>
    <line x1="${W/2}" y1="${H * 0.44 - 8}" x2="${W/2}" y2="${H * 0.44 + 8}" stroke="${LINE}" stroke-width="0.5" opacity="0.4"/>
  `)
}

function th(gender, instanceId) {
  const fig = pickFigure(gender, instanceId)
  return svg(`
    ${frameBase('TH — Talking Head')}
    <svg x="${Math.round(W * -0.12)}" y="0" width="${Math.round(W * 0.75)}" height="${H - 22}" viewBox="50 45 280 138" preserveAspectRatio="xMidYMid slice">${fig}</svg>
    <line x1="${W/3}" y1="0" x2="${W/3}" y2="${H - 22}" stroke="${LINE}" stroke-width="0.3" opacity="0.15"/>
    <line x1="${W * 2/3}" y1="0" x2="${W * 2/3}" y2="${H - 22}" stroke="${LINE}" stroke-width="0.3" opacity="0.15"/>
    <line x1="0" y1="${H / 3}" x2="${W}" y2="${H / 3}" stroke="${LINE}" stroke-width="0.3" opacity="0.12"/>
    <text x="${W - 10}" y="18" font-family="monospace" font-size="7" fill="${LINE}" opacity="0.4" text-anchor="end">headroom</text>
  `)
}

// ─── SVG WRAPPER ─────────────────────────────────────────────────────────────
function svg(content) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">${content}</svg>`
}

// ─── EXPORTS ─────────────────────────────────────────────────────────────────
export const SHOT_TYPES = [
  { id: 'ecu',   label: 'Extreme Close-Up',  desc: 'Face only — eyes to chin. Maximum intimacy.' },
  { id: 'cu',    label: 'Close-Up',           desc: 'Head and shoulders. Emotion and reaction.' },
  { id: 'mcu',   label: 'Medium Close-Up',    desc: 'Chest up. Standard interview/talking head.' },
  { id: 'ms',    label: 'Medium Shot',        desc: 'Waist up. Natural conversational distance.' },
  { id: 'mws',   label: 'Medium Wide',        desc: 'Knees up. Shows body language and gesture.' },
  { id: 'ws',    label: 'Wide Shot',          desc: 'Full body. Subject in context of space.' },
  { id: 'ews',   label: 'Extreme Wide',       desc: 'Tiny subject. Environment dominates.' },
  { id: 'ots',   label: 'Over The Shoulder',  desc: 'Depth and relationship between subjects.' },
  { id: 'two',   label: 'Two Shot',           desc: 'Two subjects. Conversation or comparison.' },
  { id: 'low',   label: 'Low Angle',          desc: 'Camera below subject. Power and authority.' },
  { id: 'high',  label: 'High Angle',         desc: 'Camera above subject. Vulnerability.' },
  { id: 'dutch', label: 'Dutch Angle',        desc: 'Tilted frame. Tension or unease.' },
  { id: 'pov',   label: 'Point of View',      desc: 'First person. Immersive perspective.' },
  { id: 'th',    label: 'Talking Head',       desc: 'Rule-of-thirds presenter. YouTube standard.' },
]

const GENERATORS = { ecu, cu, mcu, ms, mws, ws, ews, ots, two, low, high, dutch, pov, th }

export function getShotSVG(shotId, gender = 'male', instanceId = '') {
  const gen = GENERATORS[shotId]
  if (!gen) return null
  return gen(gender, instanceId || `${shotId}-${gender}`)
}

export function getAllShots(gender = 'male') {
  return SHOT_TYPES.map(shot => ({
    ...shot,
    svg: getShotSVG(shot.id, gender),
  }))
}